/**
* Auth API client — login / me / change own password.
* Token is stored by the auth store under AUTH_TOKEN_KEY; the axios
* interceptor in api/index.ts attaches it to every request.
*/
import axios from "/node_modules/.vite/deps/axios.js?v=1bd689f6";
export const AUTH_TOKEN_KEY = "cpq_auth_token";
const RESP = (p) => p.then((r) => r.data);
export const authApi = {
	config: () => RESP(axios.get("/api/auth/config")),
	login: (username, password) => RESP(axios.post("/api/auth/login", {
		username,
		password
	})),
	me: () => RESP(axios.get("/api/auth/me")),
	changePassword: (old_password, new_password) => RESP(axios.put("/api/auth/password", {
		old_password,
		new_password
	}))
};

